# 批注数据：src/utils/plugins/validatePlugin.ts
# slug = src_utils_plugins_validatePlugin_ts
ANNOTATIONS = [
    (24, 'before', '''MARKETPLACE_ONLY_MANIFEST_FIELDS：那些只该出现在 marketplace.json 条目里、而不该出现在 plugin.json 里的字段。作者常把两者互相复制，claude plugin validate 把它们当警告报出——因为加载路径用 zod 默认行为静默剥掉所有未知键，运行时无害，但值得提醒作者。'''),
    (32, 'before', '''ValidationResult：一次校验的结果——是否成功、错误列表、警告列表、文件路径、文件类型（plugin/marketplace/skill/agent/command/hooks）。'''),
    (40, 'before', '''ValidationError：单条错误——路径、消息、可选错误码。'''),
    (46, 'before', '''ValidationWarning：单条警告——路径与消息。'''),
    (54, 'before', '''detectManifestType：根据文件名与所在目录判断是 plugin.json、marketplace.json 还是 unknown（在 .claude-plugin 目录里的大概率是 plugin.json）。'''),
    (75, 'before', '''formatZodErrors：把 zod 校验错误摊平成 ValidationError 列表，路径用点号拼接，并带上 error.code。'''),
    (92, 'before', '''checkPathTraversal：检查路径字符串里是否含父目录片段（..）。对 plugin.json 组件路径这是安全问题（逃出插件目录）；对 marketplace.json 源路径多半是解析基址的误解（路径从仓库根而非 marketplace.json 本身解析）。调用方传 hint 以附上正确解释。'''),
    (113, 'before', '''marketplaceSourceHint：当 marketplace 插件源含 .. 时生成针对性提示。多数用户以为路径相对 marketplace.json（在 .claude-plugin/ 内），但其实从仓库根解析——所以剥离前导 ../ 即可，并算出「用 X 而非 Y」的建议，而不是写死示例。'''),
    (129, 'before', '''validatePluginManifest：校验 plugin.json。读文件（区分 ENOENT/EISDIR/权限错误）、解析 JSON、先查路径穿越、再剥掉 marketplace 专有字段（转成警告而非错误），最后用 .strict() 跑 schema 并补一堆命名/版本/描述/作者的软警告。'''),
    (179, 'after', '''安全前置：在跑 schema 校验之前先扫一遍解析出的 JSON，检查 commands/agents/skills 里的字符串路径是否含 ..；即便 schema 失败也能先抓出路径穿越这类安全问题。'''),
    (221, 'after', '''marketplace 专有字段前置为警告：在 .strict() 之前先把这些字段从待校验对象里剥掉并转成警告——否则 .strict() 会把它当成未知键再报一次，造成重复。运行时这些字段会被基础 schema 静默剥掉，所以只是警告不是错误。'''),
    (247, 'after', '''严格校验：这里局部对基础 schema 调 .strict()，即便运行时加载路径是宽松的（为韧性静默剥未知键），但这是开发者工具，作者跑它想要拼写错误反馈。'''),
    (254, 'after', '''成功后的软警告：名字不是严格 kebab-case（CC 接受但 Claude.ai 同步要求）、缺版本、缺描述、缺作者——都只警告，帮助作者在 CI 里提前发现问题。'''),
    (310, 'before', '''validateMarketplaceManifest：校验 marketplace.json。结构与 plugin 类似，但路径穿越检查针对 plugins[].source（相对路径）与对象源里的 .path（git 子目录，属真实穿越尝试、保持安全措辞），并额外做重复名、版本不一致、缺插件、缺描述等检查。'''),
    (360, 'after', '''安全前置：在 schema 校验前先检查 plugins 数组里每个 source 是否含 ..；字符串源用 marketplaceSourceHint 给出友好建议，对象源里的 .path 则是真实穿越、保持安全措辞不送 hint。'''),
    (403, 'after', '''严格 schema 重建：基础 schema 为韧性是宽松的，但开发者工具要拼写反馈。这里用 .strict() 重建，并显式把 plugins 数组换成 strict 的条目 schema——因为外层 .strict() 不会 propagate 进 z.array() 的元素，必须单独覆盖才能抓到单个条目里的拼写错误。'''),
    (419, 'after', '''额外检查：空 plugins 警告；逐个查重复插件名（直接报错）；对本地源且声明了版本的条目，比对它自己的 plugin.json 版本——安装时 calculatePluginVersion 优先用 manifest 版本并静默忽略条目版本，陈旧的条目版本会造成 UI 与一个 status 显示不一致，这里提前警告。'''),
    (517, 'before', '''validateComponentFile：校验插件组件 markdown 文件（skill/agent/command）里的 YAML frontmatter。运行时加载器会静默把解析不了的 YAML 丢进调试日志并返回空对象，这里作为开发者工具要给出硬信号，揭示加载器会吞掉什么。'''),
    (551, 'after', '''类型校验：frontmatter 必须是 YAML 映射；description 必须是标量（否则运行时被丢）；name 若存在必须是字符串（技能/命令用作显示名，agent 用作 agentType 词干，非字符串会被字符串化成乱码）；allowed-tools 是字符串或字符串数组；shell 只能是 bash 或 powershell（规范化大小写以匹配运行时 parseShellFrontmatter 的行为）。'''),
    (646, 'before', '''validateHooksJson：校验插件的 hooks.json。与 frontmatter 不同，这个在运行时是硬错误（pluginLoader 用 .parse 而非 .safeParse），一个坏的 hooks.json 会让整个插件崩掉——所以这里暴露它至关重要。ENOENT 是允许的（钩子可选）。'''),
    (718, 'before', '''collectMarkdown：递归收集目录下的 .md 文件，用 withFileTypes 避免每项为文件再 stat 一次；返回绝对路径让错误信息可读。'''),
    (735, 'after', '''技能目录特例：技能用 <name>/SKILL.md——只下一层、只收 SKILL.md，匹配运行时加载器（技能目录里的孤立 .md 不加载、子目录不扫）。路径是推测性的（子目录可能没有 SKILL.md），由调用方处理 ENOENT。'''),
    (763, 'before', '''validatePluginContents：扫描插件目录里的技能、agent、命令与 hooks.json（默认组件目录；manifest 可声明自定义路径，但默认布局覆盖绝大多数插件，这是 linter 不是 loader）。每个有错误或警告的文件单独返回一条结果，干净插件返回空数组。'''),
    (814, 'before', '''validateManifest：自动探测类型的入口——既能校验单个清单文件，也能校验目录。目录优先 marketplace.json 再 plugin.json；单文件按名或内容启发式判断。'''),
    (829, 'after', '''目录分支：在 .claude-plugin 里先找 marketplace.json（优先于 plugin.json），只有 ENOENT 才回落到 plugin.json；都不是则报「目录里没有清单」。单文件则按 detectManifestType 分发，unknown 时尝试解析内容——有 plugins 数组就当 marketplace 处理。'''),
]
